"""Load, dedupe, clean, and featurise orders (single source of truth)."""

from __future__ import annotations

from typing import Any

import numpy as np
import pandas as pd

from src.config import (
    CATEGORICAL_FEATURES,
    DATA_DIR,
    FEATURE_COLUMNS,
    NUMERIC_FEATURES,
)

# Re-export rate-based copy helpers (all clerk wording lives in src.reasons).
from src.reasons import (  # noqa: E402
    STATE_NAMES,
    build_rate_lookup,
    rate_sentence,
    safety_summary,
    select_reason_payload,
)

REASON_TEMPLATES = {
    "note": "Clerk-facing copy is generated by src.reasons.rate_sentence from training rates.",
}


def data_paths(data_dir: Any = None) -> dict[str, Any]:
    from pathlib import Path

    root = Path(data_dir) if data_dir is not None else DATA_DIR
    return {
        "train": root / "train.csv",
        "test": root / "test_unlabelled.csv",
        "customers": root / "customers.csv",
        "products": root / "products.csv",
        "sample": root / "sample_submission.csv",
    }


def load_raw(data_dir: Any = None) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    paths = data_paths(data_dir)
    train = pd.read_csv(paths["train"])
    test = pd.read_csv(paths["test"])
    customers = pd.read_csv(paths["customers"])
    products = pd.read_csv(paths["products"])
    return train, test, customers, products


def dedupe_train(train: pd.DataFrame) -> pd.DataFrame:
    """Keep the crm copy when partner_feed re-imports duplicate the same order_id."""
    if "source" not in train.columns:
        return train.drop_duplicates(subset=["order_id"], keep="first").copy()
    # Prefer crm over partner_feed
    ranked = train.copy()
    ranked["_src_rank"] = ranked["source"].map({"crm": 0, "partner_feed": 1}).fillna(2)
    ranked = ranked.sort_values(["order_id", "_src_rank"])
    out = ranked.drop_duplicates(subset=["order_id"], keep="first").drop(columns=["_src_rank"])
    return out.reset_index(drop=True)


def fix_october_inflation(df: pd.DataFrame) -> pd.DataFrame:
    """October 2025 order_value_inr values are inflated 100x by the new payment gateway."""
    out = df.copy()
    ts = pd.to_datetime(out["order_placed_at"])
    mask = (ts.dt.year == 2025) & (ts.dt.month == 10)
    out.loc[mask, "order_value_inr"] = out.loc[mask, "order_value_inr"] / 100.0
    return out


def join_dimensions(
    orders: pd.DataFrame, customers: pd.DataFrame, products: pd.DataFrame
) -> pd.DataFrame:
    out = orders.merge(customers, on="customer_id", how="left", validate="many_to_one")
    out = out.merge(products, on="sku", how="left", validate="many_to_one")
    return out


def _featurise_frame(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    ts = pd.to_datetime(out["order_placed_at"])
    out["hour"] = ts.dt.hour.astype(int)
    out["dow"] = ts.dt.dayofweek.astype(int)
    out["month"] = ts.dt.month.astype(int)

    value = out["order_value_inr"].astype(float).clip(lower=0)
    out["value"] = value
    out["log_value"] = np.log1p(value)

    out["discount_pct"] = out["discount_pct"].astype(float)
    out["qty"] = out["qty"].astype(float)
    out["promised_delivery_days"] = out["promised_delivery_days"].astype(float)
    out["customer_prior_orders"] = out["customer_prior_orders"].astype(float)
    out["customer_prior_returns"] = out["customer_prior_returns"].astype(float)
    out["prior_ret_rate"] = out["customer_prior_returns"] / (
        out["customer_prior_orders"] + 1.0
    )

    pin = out["delivery_pincode"].astype(str).str.strip()
    out["pin_missing"] = (pin.isin(["000000", "0", "nan", ""]) | pin.isna()).astype(int)

    note = out["delivery_note"]
    out["note_missing"] = (
        note.isna() | (note.astype(str).str.strip() == "") | (note.astype(str).str.lower() == "nan")
    ).astype(int)

    signup = pd.to_datetime(out["signup_date"], errors="coerce")
    out["cust_since_days"] = (ts - signup).dt.days.fillna(0).clip(lower=0).astype(float)

    list_price = out["list_price_inr"].astype(float).replace(0, np.nan)
    out["price_ratio"] = (value / list_price).fillna(1.0).astype(float)
    out["warranty_months"] = out["warranty_months"].astype(float)

    out["sales_channel"] = out["sales_channel"].astype(str)
    out["payment_mode"] = out["payment_mode"].astype(str)
    out["is_gift"] = out["is_gift"].astype(str).str.upper().replace({"TRUE": "Y", "FALSE": "N"})
    out["family"] = out["family"].astype(str)
    out["state"] = out["state"].astype(str)
    out["shield_member"] = (
        out["shield_member"].astype(str).str.upper().replace({"TRUE": "Y", "FALSE": "N"})
    )

    keep = ["order_id", "order_placed_at"] + FEATURE_COLUMNS
    if "returned" in out.columns:
        keep = keep + ["returned"]
    # Preserve leakage cols only for audit/ablation when present
    for c in ("last_service_event_type", "pickup_scheduled_at", "source"):
        if c in out.columns:
            keep.append(c)
    return out[keep].copy()


def prepare_orders(
    orders: pd.DataFrame,
    customers: pd.DataFrame,
    products: pd.DataFrame,
    *,
    is_train: bool = True,
) -> pd.DataFrame:
    """Full hygiene + feature pipeline for train or test."""
    df = orders.copy()
    if is_train:
        df = dedupe_train(df)
    df = fix_october_inflation(df)
    df = join_dimensions(df, customers, products)
    return _featurise_frame(df)


def load_prepared(data_dir: Any = None) -> tuple[pd.DataFrame, pd.DataFrame]:
    train_raw, test_raw, customers, products = load_raw(data_dir)
    train = prepare_orders(train_raw, customers, products, is_train=True)
    test = prepare_orders(test_raw, customers, products, is_train=False)
    return train, test


def matrix_from_frame(df: pd.DataFrame) -> pd.DataFrame:
    """Return model matrix with categoricals as pandas string dtype for HGB."""
    X = df[FEATURE_COLUMNS].copy()
    for c in CATEGORICAL_FEATURES:
        X[c] = X[c].astype("category")
    for c in NUMERIC_FEATURES:
        X[c] = pd.to_numeric(X[c], errors="coerce").fillna(0.0)
    return X


def reference_values(train_df: pd.DataFrame) -> dict[str, Any]:
    """Training medians / modes used for occlusion explanations."""
    refs: dict[str, Any] = {}
    for c in NUMERIC_FEATURES:
        refs[c] = float(pd.to_numeric(train_df[c], errors="coerce").median())
    for c in CATEGORICAL_FEATURES:
        refs[c] = train_df[c].astype(str).mode().iloc[0]
    return refs


def reason_text(
    field: str,
    value: Any,
    row: pd.Series,
    rates: dict[str, Any] | None = None,
    *,
    direction: str = "up",
) -> str:
    """Map a field + value to a short ops-readable sentence (rate-based when rates given)."""
    if rates is None:
        rates = {"overall": 0.1142}
    return rate_sentence(field, value, row, rates, direction=direction)


def score_band(score: float, threshold: float) -> tuple[str, str]:
    """Return (band label, decision sentence)."""
    if score < threshold:
        return "Ship", "Low predicted risk - ship as usual."
    if score < threshold * 2.5:
        return "Call before dispatch", (
            "Elevated return risk - confirm address/model with the customer before dispatch."
        )
    return "Hold", (
        "High return risk - review before dispatch; prefer a confirmation call over a blind hold."
    )
